18n system. Messages resolve\n * eagerly at build time, so a locale switch requires rebuilding the schemas.\n */\nexport function createAuthSchemas(t: AuthSchemaTranslate) {\n  const apiKeySchema = z.object({\n    apiKey: z\n      .string()\n      .trim()\n      .startsWith('comfyui-', t('validation.prefix', { prefix: 'comfyui-' }))\n      .length(72, t('validation.length', { length: 72 }))\n  })\n\n  const signInSchema = z.object({\n    email: z\n      .string()\n      .email(t('validation.invalidEmail'))\n      .min(1, t('validation.required')),\n    password: z.string().min(1, t('validation.required'))\n  })\n\n  const passwordSchema = z.object({\n    password: z\n      .string()\n      .min(\n        PASSWORD_RULES.minLength,\n        t('validation.minLength', { length: PASSWORD_RULES.minLength })\n      )\n      .max(\n        PASSWORD_RULES.maxLength,\n        t('validation.maxLength', { length: PASSWORD_RULES.maxLength })\n      )\n      .regex(PASSWORD_RULES.uppercase, t('validation.password.uppercase'))\n      .regex(PASSWORD_RULES.lowercase, t('validation.password.lowercase'))\n      .regex(PASSWORD_RULES.number, t('validation.password.number'))\n      .regex(PASSWORD_RULES.special, t('validation.password.special')),\n    confirmPassword: z.string().min(1, t('validation.required'))\n  })\n\n  const updatePasswordSchema = passwordSchema.refine(\n    (data) => data.password === data.confirmPassword,\n    {\n      message: t('validation.password.match'),\n      path: ['confirmPassword']\n    }\n  )\n\n  const signUpSchema = passwordSchema\n    .extend({\n      email: z\n        .string()\n        .email(t('validation.invalidEmail'))\n        .min(1, t('validation.required'))\n    })\n    .refine((data) => data.password === data.confirmPassword, {\n      message: t('validation.password.match'),\n      path: ['confirmPassword']\n    })\n\n  return { apiKeySchema, signInSchema, updatePasswordSchema, signUpSchema }\n}\n\ntype AuthSchemas = ReturnType<typeof createAuthSchemas>\n\nexport type SignInData = z.infer<AuthSchemas['signInSchema']>\nexport type SignUpData = z.infer<AuthSchemas['signUpSchema']>\n","import { createAuthSchemas } from '@comfyorg/account-core/signInSchemas'\n\nimport { t } from '@/i18n'\n\nexport type {\n  SignInData,\n  SignUpData\n} from '@comfyorg/account-core/signInSchemas'\n\nexport const {\n  apiKeySchema,\n  signInSchema,\n  updatePasswordSchema,\n  signUpSchema\n} = createAuthSchemas(t)\n"],"mappings":"kIA6BA,IAAa,EAAiB,CAC5B,UAAW,EACX,UAAW,GACX,UAAW,QACX,UAAW,QACX,OAAQ,KACR,QAAS,cACX,EASA,SAAgB,mBACd,EACyC,CACzC,MAAO,CACL,OACE,EAAS,QAAU,EAAe,WAClC,EAAS,QAAU,EAAe,UACpC,UAAW,EAAe,UAAU,KAAK,CAAQ,EACjD,UAAW,EAAe,UAAU,KAAK,CAAQ,EACjD,OAAQ,EAAe,OAAO,KAAK,CAAQ,EAC3C,QAAS,EAAe,QAAQ,KAAK,CAAQ,CAC/C,CACF,CAOA,SAAgB,kBAAkB,EAAwB,CACxD,IAAM,EAAe,EAAS,CAC5B,OAAQ,EACE,CAAC,CACR,KAAK,CAAC,CACN,WAAW,WAAY,EAAE,oBAAqB,CAAE,OAAQ,UAAW,CAAC,CAAC,CAAC,CACtE,OAAO,GAAI,EAAE,oBAAqB,CAAE,OAAQ,EAAG,CAAC,CAAC,CACtD,CAAC,EAEK,EAAe,EAAS,CAC5B,MAAO,EACG,CAAC,CACR,MAAM,EAAE,yBAAyB,CAAC,CAAC,CACnC,IAAI,EAAG,EAAE,qBAAqB,CAAC,EAClC,SAAU,EAAS,CAAC,CAAC,IAAI,EAAG,EAAE,qBAAqB,CAAC,CACtD,CAAC,EAEK,EAAiB,EAAS,CAC9B,SAAU,EACA,CAAC,CACR,IACC,EAAe,UACf,EAAE,uBAAwB,CAAE,OAAQ,EAAe,SAAU,CAAC,CAChE,CAAC,CACA,IACC,EAAe,UACf,EAAE,uBAAwB,CAAE,OAAQ,EAAe,SAAU,CAAC,CAChE,CAAC,CACA,MAAM,EAAe,UAAW,EAAE,+BAA+B,CAAC,CAAC,CACnE,MAAM,EAAe,UAAW,EAAE,+BAA+B,CAAC,CAAC,CACnE,MAAM,EAAe,OAAQ,EAAE,4BAA4B,CAAC,CAAC,CAC7D,MAAM,EAAe,QAAS,EAAE,6BAA6B,CAAC,EACjE,gBAAiB,EAAS,CAAC,CAAC,IAAI,EAAG,EAAE,qBAAqB,CAAC,CAC7D,CAAC,EAsBD,MAAO,CAAE,eAAc,eAAc,qBApBR,EAAe,OACzC,GAAS,EAAK,WAAa,EAAK,gBACjC,CACE,QAAS,EAAE,2BAA2B,EACtC,KAAM,CAAC,iBAAiB,CAC1B,CAemC,EAAsB,aAZtC,EAClB,OAAO,CACN,MAAO,EACG,CAAC,CACR,MAAM,EAAE,yBAAyB,CAAC,CAAC,CACnC,IAAI,EAAG,EAAE,qBAAqB,CAAC,CACpC,CAAC,CAAC,CACD,OAAQ,GAAS,EAAK,WAAa,EAAK,gBAAiB,CACxD,QAAS,EAAE,2BAA2B,EACtC,KAAM,CAAC,iBAAiB,CAC1B,CAEyD,CAAa,CAC1E,CC/GA,GAAa,CACX,eACA,eACA,uBACA,gBACE,kBAAkB,CAAC"}"""

